    thumbnail:
      'https://is1-ssl.mzstatic.com/image/thumb/Purple221/v4/ad/03/17/ad0317a9-33dd-94b2-3075-be6ffc1a6174/AppIcon-1x_U007emarketing-0-7-0-85-220-0.png/512x512bb.jpg',
    rating: 4.73737,
    downloads_min: 0,
