    thumbnail:
      'https://is1-ssl.mzstatic.com/image/thumb/Purple126/v4/68/0f/fa/680ffa95-98a4-d952-67a5-b0637bfcbec9/AppIcon-1x_U007emarketing-0-7-0-85-220.png/512x512bb.jpg',
