      'https://is1-ssl.mzstatic.com/image/thumb/Purple126/v4/02/fd/11/02fd111c-9aff-9366-00e6-99759897e1ed/AppIcon-1x_U007emarketing-0-7-0-85-220-0.png/512x512bb.jpg',
    rating: 4.72089,
    downloads_min: 0,
    downloads_max: 0,
    website: 'https://www.igg.com',
    app_size_kb: 1227225,
    contains_ads: 0,
