    app_title: 'Battlegrounds Mobile India',
    short_description: 'No Time? No worries! BGMI Quick game modes and Mecha Fusion Mode got you covered',
    thumbnail:
      'https://play-lh.googleusercontent.com/DYXNS7NyuIgbCk5ElbK2Ch7dNuUnnCJ2ToDsV0QK0Q-MiGWQR7oDl9w8VXGinA5ureA',
    rating: 4.2017,
