    app_title: 'Hole and Fill: Collect Master!',
    short_description: 'Enjoy and relax as you fill the fridge, eat everything in these sorting games!',
    thumbnail:
      'https://play-lh.googleusercontent.com/o4hxcUlS9MD0JbuIHXBZXHhVLDbyQ-lobGbTGpHLwUI8HYKYrwPWXH6Xx2QzpVQ65Ig',
    rating: 4.30748,
    downloads_min: 10000000,
