    preview_url: 'https://play.google.com/store/apps/details?id=com.forcegames.tiledreams',
    app_title: 'Tile Dreams - Relaxing Puzzle',
    short_description: 'Tile Matching Mahjong Game',
    thumbnail:
      'https://play-lh.googleusercontent.com/rXO33nojGkpTU9eO6l9IMzcIvmYF3_9G4MXphW4sycZFNpHnB8L9h5pgRj-HKDoHS9Y',
