    app_title: 'Bloodline: Heroes of Lithas',
    short_description: 'A game where legendary heroes are not just found in a loot crate.',
    thumbnail:
      'https://play-lh.googleusercontent.com/OTgwDswAiQwz8uIG19t8wf4ss5nVA_jycsqAIMUZzXKtAfThmlfnz_51rLx8kezjmss',
