    app_title: 'Hero Adventure: Survivor RPG',
    short_description: 'Heroic adventure in a dungeon. A shooter game with Roguelike &amp; RPG elements.',
    thumbnail:
      'https://play-lh.googleusercontent.com/vR_DpTUC_hB_1kEswBssGqj_AKRsugMHQbQk-AaZTs8S3DxYQhgoK44YO7onnpjlYfY',
