    preview_url: 'https://play.google.com/store/apps/details?id=farm.parking.game',
    app_title: 'Farm Jam: Animal Parking Game',
    short_description: 'Cute combo of parking games and farm animal games on a township farm',
    thumbnail:
      'https://play-lh.googleusercontent.com/AHJ470I_EiofNDmkN0PlgDxcTq6kxE0lOgux9rW_j1EkikwZB865hC6oAWM5zlkkWD-4',
