    app_title: 'Lords Mobile: Kingdom Wars',
    short_description: 'Wage MMORPG battles in this strategy game! Conquer kingdoms to build an empire!',
    thumbnail:
      'https://play-lh.googleusercontent.com/oFz-KTIgL6yAuuA5XeHapTQLDcoBVgA9JXCTiID70rPcJBGAT9DdiqNDjNLxcYaG6W3W',
    rating: 4.39223,
